-- Canonical business identifiers and closed source-to-intent mapping.
ALTER TABLE "NotificationDeliveryAttempt" ALTER COLUMN result SET DEFAULT 'CAPTURE_INTENT';
CREATE FUNCTION notification_canonical_contract() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE expected text; s "NotificationSource"; valid boolean;
BEGIN
 IF TG_TABLE_NAME='NotificationSource' THEN
  expected:=NEW.kind||':'||CASE NEW.kind WHEN 'LIFECYCLE' THEN NEW."lifecycleEventId" WHEN 'MILESTONE' THEN NEW."periodId"||':'||NEW.milestone WHEN 'QUOTE' THEN NEW."requestId" WHEN 'QUOTE_ACCEPTED' THEN NEW."requestId" WHEN 'PAYMENT_SUBMITTED' THEN NEW."paymentId" WHEN 'RECEIPT' THEN NEW."receiptId" WHEN 'REVERSAL' THEN NEW."reversalId" WHEN 'PERIOD' THEN NEW."periodId" WHEN 'CHECKOUT_AUDIT' THEN NEW."auditLogId" ELSE NEW."platformAuditId" END;
  IF NEW."canonicalKey" IS DISTINCT FROM expected OR NEW."policyVersion"<>'NB-CAPTURE-v1' THEN RAISE EXCEPTION 'Noncanonical notification source'; END IF;
  IF TG_OP='UPDATE' AND OLD.state IN ('HISTORICAL_REVIEW','AUDIT_ONLY') AND NEW.state<>OLD.state THEN RAISE EXCEPTION 'Historical disposition requires separate approved review'; END IF;
  IF NEW.kind='CHECKOUT_AUDIT' AND NOT EXISTS(SELECT 1 FROM "AuditLog" a WHERE a.id=NEW."auditLogId" AND a.action='PAYSTACK_CHECKOUT_REQUESTED') THEN RAISE EXCEPTION 'Invalid checkout source'; END IF;
 ELSE
  SELECT * INTO s FROM "NotificationSource" WHERE id=NEW."sourceId";
  IF s.state IN ('HISTORICAL_REVIEW','AUDIT_ONLY') THEN RAISE EXCEPTION 'Non-actionable source'; END IF;
  valid:=CASE s.kind
   WHEN 'QUOTE' THEN NEW.kind='QUOTE_READY'
   WHEN 'QUOTE_ACCEPTED' THEN NEW.kind='QUOTE_ACCEPTED'
   WHEN 'PAYMENT_SUBMITTED' THEN NEW.kind IN ('PAYMENT_CLAIM_RECEIVED','PAYMENT_REVIEW_REQUIRED')
   WHEN 'PAYMENT_REJECTED' THEN NEW.kind='PAYMENT_REVIEW_UPDATED'
   WHEN 'RECEIPT' THEN NEW.kind='PAYMENT_VERIFIED'
   WHEN 'REVERSAL' THEN NEW.kind IN ('PAYMENT_STATUS_CHANGED','PAYMENT_REVIEW_REQUIRED')
   WHEN 'PERIOD' THEN NEW.kind='SUBSCRIPTION_CONFIRMED'
   WHEN 'REQUEST_CLOSED' THEN NEW.kind='COMMERCIAL_REQUEST_CLOSED'
   WHEN 'MILESTONE' THEN NEW.kind=CASE s.milestone WHEN 'RENEWAL_7' THEN 'RENEWAL_APPROACHING' WHEN 'EXPIRY' THEN 'EXPIRED_GRACE_STARTED' WHEN 'GRACE_5' THEN 'GRACE_ENDING' WHEN 'ARCHIVE' THEN 'WORKSPACE_ARCHIVED' WHEN 'CANCEL_46' THEN 'CANCELLATION_WARNING' WHEN 'CANCEL' THEN 'WORKSPACE_CANCELED' WHEN 'RETENTION_30' THEN 'RETENTION_END_APPROACHING_30' ELSE 'RETENTION_END_APPROACHING_7' END
   WHEN 'LIFECYCLE' THEN EXISTS(SELECT 1 FROM "WorkspaceLifecycleEvent" e WHERE e.id=s."lifecycleEventId" AND NEW.kind=ANY(CASE e.type WHEN 'EXPORT_REQUESTED' THEN ARRAY['EXPORT_REQUEST_ACCEPTED'] WHEN 'EXPORT_READY' THEN ARRAY['EXPORT_AVAILABLE'] WHEN 'EXPORT_FAILED' THEN ARRAY['EXPORT_PREPARATION_FAILED'] WHEN 'EXPORT_EXPIRED' THEN ARRAY['EXPORT_UNAVAILABLE'] WHEN 'RECOVERY_REQUESTED' THEN ARRAY['RECOVERY_REQUEST_ACCEPTED','RECOVERY_REVIEW_REQUIRED'] WHEN 'RECOVERY_APPROVED' THEN ARRAY['RECOVERY_REVIEW_UPDATED'] WHEN 'RECOVERY_REJECTED' THEN ARRAY['RECOVERY_REVIEW_UPDATED'] WHEN 'RECOVERY_REVOKED' THEN ARRAY['RECOVERY_ACCESS_WITHDRAWN'] WHEN 'RECOVERY_GRANT_EXPIRED' THEN ARRAY['RECOVERY_ACCESS_EXPIRED'] ELSE ARRAY[]::text[] END))
   ELSE false END;
  IF NOT valid OR NEW."logicalKey"<>s."canonicalKey"||':'||NEW.kind||':'||NEW."recipientUserId"||':EMAIL' OR NEW."recipientPolicyVersion"<>'NB-CAPTURE-v1' THEN RAISE EXCEPTION 'Invalid source intent contract'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER notification_canonical_source BEFORE INSERT OR UPDATE ON "NotificationSource" FOR EACH ROW EXECUTE FUNCTION notification_canonical_contract();
CREATE TRIGGER notification_canonical_outbox BEFORE INSERT OR UPDATE ON "NotificationOutbox" FOR EACH ROW EXECUTE FUNCTION notification_canonical_contract();
